/// Namespace used for top-level function and custom tools.
pub const DEFAULT_FUNCTION_NAMESPACE: &str = "functions";

/// Identifies a callable tool, preserving the namespace split when the model
/// provides one.
#[derive(Clone, Debug, Deserialize, Eq, Hash, PartialEq, Serialize)]
pub struct ToolName {
    pub name: String,
    pub namespace: Option<String>,
}

impl ToolName {
    pub fn new(namespace: Option<String>, name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            namespace,
        }
    }

    pub fn plain(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            namespace: None,
        }
    }

    pub fn namespaced(namespace: impl Into<String>, name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            namespace: Some(namespace.into()),
        }
    }

    pub fn with_default_namespace(mut self) -> Self {
        if self.namespace.as_deref().is_none_or(str::is_empty) {
            self.namespace = Some(DEFAULT_FUNCTION_NAMESPACE.to_string());
        }
        self
    }

    pub fn is_default_namespace(&self) -> bool {
        matches!(
            self.namespace.as_deref(),
            None | Some("") | Some(DEFAULT_FUNCTION_NAMESPACE)

#[instrument(level = "trace", skip_all, err)]
pub fn build_tool_call(
    &self,
    mut item: ResponseItem,
) -> Result<Option<ToolCall>, FunctionCallError> {
    match item {
        ResponseItem::FunctionCall {
            ref name,
            ref namespace,
            ref mut arguments,
            ref call_id,
            ref mut encrypted_function_args,
            ..
        } => {
            let tool_name =
                ToolName::new(namespace.clone(), name.clone()).with_default_namespace();
            let retain_native_call = self
                .registry
                .registered_tool(&tool_name)
                .is_some_and(|tool| tool.native_review == NativeReview::Required);
            let (arguments, encrypted_function_args) = if retain_native_call {
                (arguments.clone(), encrypted_function_args.clone())
            } else {
                (std::mem::take(arguments), encrypted_function_args.take())
            };
            let call_id = call_id.clone();
            Ok(Some(ToolCall {
                tool_name,
                call_id,
                payload: ToolPayload::Function { arguments },
                encrypted_function_args,
                native_call: retain_native_call.then(|| Arc::new(item)),
            }))
        }

